exact.// 1. LED 깜박이기\n// 13번 핀 → 220Ω 저항 → LED:
// 1. Blink an LED
// Pin 13 → 220Ω resistor → LED long leg (+), LED short leg (−) → GND
// The L LED on the board blinks too.

const int ledPin = 13;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  digitalWrite(ledPin, HIGH);  // on
  delay(1000);                 // wait 1 second
  digitalWrite(ledPin, LOW);   // off
  delay(1000);
}

exact.// 10. RGB LED로 색 섞기\n// R, G, B 세기를 PWM:
// 10. Mix colors with an RGB LED
// Set the R, G, B brightness with PWM to make colors.

const int redPin = 9;
const int greenPin = 10;
const int bluePin = 11;

void setColor(int r, int g, int b) {
  analogWrite(redPin, r);
  analogWrite(greenPin, g);
  analogWrite(bluePin, b);
}

void setup() {}

void loop() {
  setColor(255, 0, 0);     // red
  delay(1000);
  setColor(0, 255, 0);     // green
  delay(1000);
  setColor(0, 0, 255);     // blue
  delay(1000);
  setColor(255, 255, 0);   // yellow
  delay(1000);
  setColor(0, 255, 255);   // sky blue
  delay(1000);
  setColor(255, 0, 255);   // purple
  delay(1000);
}

exact.// 2. 신호등\n// 초록 → 노랑 → 빨강 순서로 켭니다.\n//:
// 2. Traffic light
// Lights green → yellow → red in order.
// Each LED needs its own resistor.

const int red = 12;
const int yellow = 11;
const int green = 10;

void setup() {
  pinMode(red, OUTPUT);
  pinMode(yellow, OUTPUT);
  pinMode(green, OUTPUT);
}

// Turn on just one LED and wait ms (milliseconds).
void light(int pin, int ms) {
  digitalWrite(red, LOW);
  digitalWrite(yellow, LOW);
  digitalWrite(green, LOW);
  digitalWrite(pin, HIGH);
  delay(ms);
}

void loop() {
  light(green, 3000);
  light(yellow, 1000);
  light(red, 3000);
}

exact.// 3. 버튼으로 LED 켜기\n// INPUT_PULLUP: 평소 H:
// 3. Turn on an LED with a button
// INPUT_PULLUP: normally HIGH, LOW when pressed.
// Press the button on the canvas with the mouse.

const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {   // when pressed
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
}

exact.// 4. 가변저항으로 LED 밝기 조절\n// analogRead()는:
// 4. Control LED brightness with a potentiometer
// analogRead() gives 0–1023, analogWrite() takes 0–255.
// Turn the potentiometer with the mouse wheel.

const int potPin = A0;
const int ledPin = 9;    // PWM pin marked with ~

void setup() {
  Serial.begin(9600);
}

void loop() {
  int value = analogRead(potPin);
  int brightness = map(value, 0, 1023, 0, 255);
  analogWrite(ledPin, brightness);

  Serial.print("Potentiometer: ");
  Serial.print(value);
  Serial.print("  Brightness: ");
  Serial.println(brightness);
  delay(200);
}

exact.// 5. 조도 센서로 자동 조명 만들기\n// 어두워지면 LED가 켜집:
// 5. Make an automatic light with a light sensor
// The LED turns on when it gets dark.
// Select the light sensor and change the brightness in the left panel.

const int sensorPin = A0;
const int ledPin = 9;
const int threshold = 300;   // turn on if darker than this

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(sensorPin);   // brighter = larger value
  Serial.print("Light value: ");
  Serial.println(light);

  if (light < threshold) {
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
  delay(300);
}

exact.// 6. 부저로 음계 연주하기\n// tone(핀, 주파수, 길이)로:
// 6. Play a musical scale with a buzzer
// tone(pin, frequency, duration) makes a sound.

#define NOTE_C4 262
#define NOTE_D4 294
#define NOTE_E4 330
#define NOTE_F4 349
#define NOTE_G4 392
#define NOTE_A4 440
#define NOTE_B4 494
#define NOTE_C5 523

const int buzzerPin = 8;
int melody[] = {NOTE_C4, NOTE_D4, NOTE_E4, NOTE_F4, NOTE_G4, NOTE_A4, NOTE_B4, NOTE_C5};

void setup() {}

void loop() {
  for (int i = 0; i < 8; i++) {
    tone(buzzerPin, melody[i], 250);
    delay(300);
  }
  delay(1000);
}

exact.// 7. 가변저항으로 서보 모터 각도 조절\n// 가변저항 값(0~10:
// 7. Control a servo motor angle with a potentiometer
// Converts the potentiometer value (0–1023) to an angle (0–180).
#include <Servo.h>

Servo myServo;
const int potPin = A0;

void setup() {
  myServo.attach(9);
  Serial.begin(9600);
}

void loop() {
  int value = analogRead(potPin);
  int angle = map(value, 0, 1023, 0, 180);
  myServo.write(angle);

  Serial.print("Angle: ");
  Serial.println(angle);
  delay(50);
}

exact.// 8. 초음파 센서로 주차 경보기 만들기\n// 가까울수록 부저가 빠:
// 8. Make a parking alarm with an ultrasonic sensor
// The closer it is, the faster the buzzer beeps.
// Select the ultrasonic sensor and change the distance.

const int trigPin = 7;
const int echoPin = 6;
const int buzzerPin = 4;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  Serial.begin(9600);
}

float readDistance() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);   // send a 10µs pulse
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  long duration = pulseIn(echoPin, HIGH);
  return duration / 58.0;        // convert to cm
}

void loop() {
  float distance = readDistance();
  Serial.print("Distance: ");
  Serial.print(distance, 1);
  Serial.println(" cm");

  if (distance > 0 && distance < 10) {
    tone(buzzerPin, 1000);       // very close: beep nonstop
    delay(200);
  } else if (distance > 0 && distance < 50) {
    tone(buzzerPin, 1000, 100);
    delay(distance * 10);        // closer = shorter pause
  } else {
    noTone(buzzerPin);
    delay(200);
  }
}

exact.// 9. 온습도를 LCD에 표시하기\n// DHT11 온습도를 I2C:
// 9. Show temperature and humidity on an LCD
// Shows DHT11 temperature and humidity on an I2C LCD.
// LCD: SDA → A4, SCL → A5
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2);   // address, columns, rows

void setup() {
  dht.begin();
  lcd.init();
  lcd.backlight();
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();

  lcd.setCursor(0, 0);
  if (isnan(t) || isnan(h)) {
    lcd.print("Sensor error    ");
  } else {
    lcd.print("Temp: ");
    lcd.print(t, 1);
    lcd.print((char)223);         // ° symbol
    lcd.print("C   ");
    lcd.setCursor(0, 1);
    lcd.print("Humi: ");
    lcd.print(h, 0);
    lcd.print(" %    ");
  }
  delay(2000);
}

